grep -n "^import\|^from\|import " /workspace/submission/main.py | grep -v "^#" ; echo "---"; python3 -c "
import ast
t = ast.parse(open('/workspace/submission/main.py').read())
mods = set()
for n in ast.walk(t):
    if isinstance(n, ast.Import):
        for a in n.names: mods.add(a.name.split('.')[0])
    elif isinstance(n, ast.ImportFrom):
        mods.add((n.module or '').split('.')[0])
print('imports:', sorted(mods))
import sys
print('all stdlib:', all(m in sys.stdlib_module_names for m in mods))"
